    /// </summary>
    abstract characterDataOldValue: bool option with get, set
    /// <summary>
    /// Set to true if mutations to target's children are to be observed.
    /// </summary>
    abstract childList: bool option with get, set
    /// <summary>
    /// Set to true if mutations to not just target, but also target's descendants are to be observed.
    /// </summary>
    abstract subtree: bool option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (?attributeFilter: string[], ?attributeOldValue: bool, ?attributes: bool, ?characterData: bool, ?characterDataOldValue: bool, ?childList: bool, ?subtree: bool) : MutationObserverInit = jsNative

