    abstract CAPTURING_PHASE: float
    abstract AT_TARGET: float
    abstract BUBBLING_PHASE: float

type DeviceOrientationEventConstructor =
    [<EmitConstructor>]
    abstract Create: ``type``: string * ?eventInitDict: DeviceOrientationEventInit -> DeviceOrientationEvent

/// <summary>
/// Available only in secure contexts.
/// </summary>
[<Interface>]
type DigitalCredential =
    inherit Credential
    abstract data: obj
    abstract protocol: string
    abstract toJSON: unit -> obj
    /// <summary>
    /// The **<c>id</c>** read-only property of the Credential interface returns a string containing the credential's identifier. This might be a GUID, username, or email address, or some other value, depending on the type of credential.
    ///
    /// [MDN Reference](https://developer.mozilla.org/docs/Web/API/Credential/id)
    /// </summary>
    abstract id: string
    /// <summary>
    /// The **<c>type</c>** read-only property of the Credential interface returns a string containing the credential's type. Valid values are password, federated, public-key, identity and otp.
    ///
    /// [MDN Reference](https://developer.mozilla.org/docs/Web/API/Credential/type)
    /// </summary>
    abstract ``type``: string
    [<ParamObject; Emit("$0")>]
    static member Create (data: obj, protocol: string, toJSON: (unit -> obj), id: string, ``type``: string) : DigitalCredential = jsNative

type DigitalCredentialConstructor =
    abstract userAgentAllowsProtocol: protocol: string -> bool
    [<EmitConstructor>]
    abstract Create: unit -> DigitalCredential

